export function statusLabel(status: TicketStatus) {
  if (status === "open") {
    return "Open";
  }
  return "Closed";
}

edits.newText:
export function statusLabel(status: TicketStatus) {
  if (status === "open") {
    return "Open";
  }
  if (status === "archived") {
    return "Archived";
  }
  return "Closed";
}
